import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';
import { z } from 'zod';

const t = initTRPC.create();

export const appRouter = t.router({
  countdown: t.procedure
    .input(z.number().int().nonnegative())
    .subscription(async function* (opts) {
      const n = opts.input;
      for (let i = n; i >= 0; i--) {
        yield i;
        await new Promise((resolve) => setTimeout(resolve, 100));
      }
    }),
});

export type AppRouter = typeof appRouter;

const server = createHTTPServer({
  router: appRouter,
});

server.listen(3000, () => {
  console.log('tRPC server listening on http://localhost:3000');
});

import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import { writeFileSync } from 'fs';
import { resolve } from 'path';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  const values: number[] = [];

  await new Promise<void>((resolvePromise, rejectPromise) => {
    client.countdown.subscribe(5, {
      onData(value) {
        values.push(value);
      },
      onComplete() {
        resolvePromise();
      },
      onError(err) {
        rejectPromise(err);
      },
    });
  });

  const outputPath = resolve('/home/user/project/output.json');
  writeFileSync(outputPath, JSON.stringify(values));
  console.log('Wrote output:', values);
  console.log('Output path:', outputPath);
}

main().catch((err) => {
  console.error('Client error:', err);
  process.exit(1);
});

