    const lines = rawEvent.split('\n');
    for (const line of lines) {
      if (line.startsWith('event:')) {
        eventField = line.slice(6).trim();
      } else if (line.startsWith('data:')) {
        dataLines.push(line.slice(5).replace(/^ /, ''));
      } else if (line.startsWith('id:')) {
        idField = line.slice(3).trim();
        if (idField) {
          this.lastEventId = idField;
        }
      }
      // Ignore comment lines (starting with ':') and retry lines
    }

    const data = dataLines.join('\n');
    const messageEvent: PolyfillMessageEvent = {
      data,
      lastEventId: idField,
    };

    this.dispatchEvent(eventField, messageEvent);
  }

  private dispatchEvent(type: string, event: Partial<PolyfillMessageEvent>) {
    const listeners = this.listeners.get(type);
    if (listeners) {
      for (const listener of listeners) {
        try {
          listener(event as Event);
        } catch {
          // ignore listener errors
        }
      }
    }
  }

  addEventListener(type: string, listener: EventSourceListener): void {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }
    this.listeners.get(type)!.add(listener);
  }

  removeEventListener(type: string, listener: EventSourceListener): void {
    this.listeners.get(type)?.delete(listener);
  }

  close(): void {
    this.abortController.abort();
    this.readyState = CLOSED;
  }
}

export { PolyfillEventSource as EventSource };

import { createTRPCClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import { writeFileSync } from 'fs';
import { resolve } from 'path';
import { EventSource } from './eventsource-polyfill';

const client = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
      EventSource: EventSource as never,
    }),
  ],
});

async function main() {
  const values: number[] = [];

  await new Promise<void>((resolvePromise, rejectPromise) => {
    client.countdown.subscribe(5, {
      onData(value) {
        values.push(value);
      },
      onComplete() {
        resolvePromise();
      },
      onError(err) {
        rejectPromise(err);
      },
    });
  });

  const outputPath = resolve('/home/user/project/output.json');
  writeFileSync(outputPath, JSON.stringify(values));
  console.log('Wrote output:', values);
  console.log('Output path:', outputPath);
}

main().catch((err) => {
  console.error('Client error:', err);
  process.exit(1);
});
